var GlobalCrypto := 0
var GlobalWaves := 0
var GlobalServerHealth := 0
var GlobalMonsterAmount := 0
var first_antivirus_placed := false

func reset_run_state() -> void:
	GlobalCrypto = 0
	GlobalWaves = 0
	GlobalServerHealth = 0
	GlobalMonsterAmount = 0
