func spend_crypto(amount: int) -> bool:
	if amount <= 0:
		return true
	if GlobalCrypto < amount:
		return false
	GlobalCrypto -= amount
	return true

func _ready() -> void:
	pass

func _process(_delta: float) -> void:
	pass
