extends Node

signal wave_started(wave_number: int)
signal wave_cleared(next_wave_number: int)
signal wave_updated(wave_number: int, enemies_remaining: int, state: String)

enum WaveState {
	WAITING,
	SPAWNING,
	IN_PROGRESS,
	CLEARED
}

@export_node_path("Node") var enemy_spawner_path: NodePath = ^"../EnemySpawner"
@export_node_path("Button") var start_wave_button_path: NodePath = ^"../BuildModeUI/StartWaveButton"
@export_node_path("Label") var wave_label_path: NodePath = ^"../BuildModeUI/WaveLabel"
@export var starting_enemy_count: int = 3
@export var enemies_added_per_wave: int = 2
@export var health_increase_per_wave: float = 0.08
@export var damage_increase_per_wave: float = 0.05
@export var spawn_interval: float = 1.0
@export var base_enemy_health: float = 50.0
@export var base_enemy_damage: float = 10.0

@onready var enemy_spawner: Node = get_node_or_null(enemy_spawner_path)
@onready var start_wave_button: Button = get_node_or_null(start_wave_button_path)
@onready var wave_label: Label = get_node_or_null(wave_label_path)

var current_wave: int = 1
var state: int = WaveState.WAITING
var _spawn_timer: SceneTreeTimer = null
var _active_wave_id: int = 0
var _enemies_to_spawn: int = 0
var _enemies_spawned: int = 0
var _tracked_enemies: Dictionary = {}
var _wave_completed := false

func _ready() -> void:
	Global.GlobalWaves = current_wave
	if start_wave_button != null and not start_wave_button.pressed.is_connected(_on_start_wave_pressed):
		start_wave_button.pressed.connect(_on_start_wave_pressed)
	_update_ui()

func _on_start_wave_pressed() -> void:
	start_current_wave()

func start_current_wave() -> void:
	if state == WaveState.SPAWNING or state == WaveState.IN_PROGRESS:
		return
	if enemy_spawner == null or not enemy_spawner.has_method("spawn_enemy_for_wave"):
		push_error("WaveManager: EnemySpawner missing or incompatible.")
		return
	_wave_completed = false
	_tracked_enemies.clear()
	_active_wave_id += 1
	_enemies_spawned = 0
	_enemies_to_spawn = get_enemy_count_for_wave(current_wave)
	state = WaveState.SPAWNING
	Global.GlobalWaves = current_wave
	if start_wave_button != null:
		start_wave_button.visible = false
	emit_signal("wave_started", current_wave)
	_update_ui()
	_call_spawn_loop(_active_wave_id)

func get_enemy_count_for_wave(wave_number: int) -> int:
	return max(1, starting_enemy_count + (wave_number - 1) * enemies_added_per_wave)

func get_enemy_health_for_wave(wave_number: int) -> float:
	return base_enemy_health * (1.0 + health_increase_per_wave * float(max(wave_number - 1, 0)))

func get_enemy_damage_for_wave(wave_number: int) -> float:
	return base_enemy_damage * (1.0 + damage_increase_per_wave * float(max(wave_number - 1, 0)))

func _call_spawn_loop(wave_id: int) -> void:
	_spawn_next_enemy(wave_id)

func _spawn_next_enemy(wave_id: int) -> void:
	if wave_id != _active_wave_id:
		return
	if state != WaveState.SPAWNING:
		return
	if _enemies_spawned >= _enemies_to_spawn:
		state = WaveState.IN_PROGRESS
		_update_ui()
		_check_wave_completion()
		return
	var stats := {
		"max_health": get_enemy_health_for_wave(current_wave),
		"attack_damage": get_enemy_damage_for_wave(current_wave)
	}
	var enemy = enemy_spawner.spawn_enemy_for_wave(stats)
	if enemy != null:
		_register_enemy(enemy)
		_enemies_spawned += 1
		_update_ui()
	_spawn_timer = get_tree().create_timer(max(spawn_interval, 0.05))
	_spawn_timer.timeout.connect(func() -> void:
		_spawn_next_enemy(wave_id)
	)

func _register_enemy(enemy: Node) -> void:
	if enemy == null or not is_instance_valid(enemy):
		return
	var id := enemy.get_instance_id()
	if _tracked_enemies.has(id):
		return
	_tracked_enemies[id] = enemy
	if enemy.has_signal("died") and not enemy.died.is_connected(_on_enemy_died):
		enemy.died.connect(_on_enemy_died)
	if not enemy.tree_exited.is_connected(_on_enemy_tree_exited.bind(id)):
		enemy.tree_exited.connect(_on_enemy_tree_exited.bind(id))

func _on_enemy_died(enemy: Node) -> void:
	_unregister_enemy(enemy)

func _on_enemy_tree_exited(enemy_id: int) -> void:
	_tracked_enemies.erase(enemy_id)
	_check_wave_completion()
	_update_ui()

func _unregister_enemy(enemy: Node) -> void:
	if enemy == null:
		return
	_tracked_enemies.erase(enemy.get_instance_id())
	_check_wave_completion()
	_update_ui()

func _get_active_enemy_count() -> int:
	var invalid_ids: Array = []
	for enemy_id in _tracked_enemies.keys():
		var enemy: Node = _tracked_enemies[enemy_id]
		if enemy == null or not is_instance_valid(enemy) or enemy.is_queued_for_deletion():
			invalid_ids.append(enemy_id)
	for enemy_id in invalid_ids:
		_tracked_enemies.erase(enemy_id)
	return _tracked_enemies.size()

func _check_wave_completion() -> void:
	if _wave_completed:
		return
	if state == WaveState.WAITING or state == WaveState.CLEARED:
		return
	if _enemies_spawned < _enemies_to_spawn:
		return
	if _get_active_enemy_count() > 0:
		return
	_wave_completed = true
	state = WaveState.CLEARED
	current_wave += 1
	Global.GlobalWaves = current_wave
	if start_wave_button != null:
		start_wave_button.text = "Start Wave %d" % current_wave
		start_wave_button.visible = true
	emit_signal("wave_cleared", current_wave)
	_update_ui()
	state = WaveState.WAITING
	_update_ui()

func _update_ui() -> void:
	var enemies_remaining := max(0, (_enemies_to_spawn - _enemies_spawned) + _get_active_enemy_count()) if state == WaveState.SPAWNING else _get_active_enemy_count()
	if start_wave_button != null:
		start_wave_button.text = "Start Wave %d" % current_wave
		start_wave_button.visible = state == WaveState.WAITING or state == WaveState.CLEARED
	if wave_label != null:
		if state == WaveState.SPAWNING or state == WaveState.IN_PROGRESS:
			wave_label.text = "Wave %d — Enemies Remaining: %d" % [current_wave, enemies_remaining]
		else:
			wave_label.text = "Wave %d" % current_wave
	emit_signal("wave_updated", current_wave, enemies_remaining, _state_to_string(state))

func _state_to_string(value: int) -> String:
	match value:
		WaveState.WAITING:
			return "WAITING"
		WaveState.SPAWNING:
			return "SPAWNING"
		WaveState.IN_PROGRESS:
			return "IN_PROGRESS"
		WaveState.CLEARED:
			return "CLEARED"
		_:
			return "UNKNOWN"

extends Node2D

@export var enemy_scene: PackedScene = preload("res://Enemies/enemy.tscn")
@export_node_path("Camera2D") var camera_path: NodePath = ^"../Camera2D"
@export_node_path("TileMapLayer") var ground_path: NodePath = ^"../Ground"
@export_node_path("Node2D") var enemies_container_path: NodePath = ^"../Enemies"
@export var spawn_offset: float = 32.0
@export var max_spawn_attempts: int = 20

@onready var camera: Camera2D = get_node_or_null(camera_path) as Camera2D
@onready var ground: TileMapLayer = get_node_or_null(ground_path) as TileMapLayer
@onready var enemies_container: Node2D = get_node_or_null(enemies_container_path) as Node2D

var active_enemies: Array[Node] = []
var level: Node

func _ready() -> void:
	randomize()
	level = get_parent()

func spawn_enemy_for_wave(stat_overrides: Dictionary = {}) -> Node:
	_cleanup_enemy_list()
	if enemy_scene == null or camera == null or ground == null or enemies_container == null:
		return null
	var spawn_result := _find_spawn_position()
	if not spawn_result.get("success", false):
		return null
	var enemy := enemy_scene.instantiate()
	if enemy == null:
		return null
	_apply_enemy_stats(enemy, stat_overrides)
	enemies_container.add_child(enemy)
	enemy.global_position = spawn_result.get("position", Vector2.ZERO)
	if enemy.has_signal("died"):
		enemy.died.connect(_on_enemy_died)
	active_enemies.append(enemy)
	return enemy

func _apply_enemy_stats(enemy: Node, stat_overrides: Dictionary) -> void:
	if enemy == null:
		return
	if stat_overrides.has("max_health"):
		enemy.max_health = float(stat_overrides["max_health"])
		enemy.current_health = enemy.max_health
	if stat_overrides.has("attack_damage"):
		enemy.attack_damage = float(stat_overrides["attack_damage"])

func _on_enemy_died(enemy: Node) -> void:
	active_enemies.erase(enemy)

func _cleanup_enemy_list() -> void:
	active_enemies = active_enemies.filter(func(enemy: Node) -> bool: return enemy != null and is_instance_valid(enemy) and not enemy.is_queued_for_deletion())

func _find_spawn_position() -> Dictionary:
	var rect := _get_camera_world_rect()
	var used_rect := ground.get_used_rect()
	for _i in range(max_spawn_attempts):
		var side := randi() % 4
		var world_position := Vector2.ZERO
		match side:
			0:
				world_position = Vector2(randf_range(rect.position.x, rect.end.x), rect.position.y - spawn_offset)
			1:
				world_position = Vector2(randf_range(rect.position.x, rect.end.x), rect.end.y + spawn_offset)
			2:
				world_position = Vector2(rect.position.x - spawn_offset, randf_range(rect.position.y, rect.end.y))
			3:
				world_position = Vector2(rect.end.x + spawn_offset, randf_range(rect.position.y, rect.end.y))
		var local := ground.to_local(world_position)
		var cell := ground.local_to_map(local)
		cell.x = clampi(cell.x, used_rect.position.x, used_rect.position.x + used_rect.size.x - 1)
		cell.y = clampi(cell.y, used_rect.position.y, used_rect.position.y + used_rect.size.y - 1)
		if level != null and level.has_method("is_cell_occupied") and level.is_cell_occupied(cell):
			continue
		var adjusted_world := ground.to_global(ground.map_to_local(cell))
		if level != null and level.has_method("is_world_position_near_structure") and level.is_world_position_near_structure(adjusted_world, 12.0):
			continue
		return {"success": true, "position": adjusted_world}
	return {"success": false, "position": Vector2.ZERO}

func _get_camera_world_rect() -> Rect2:
	var viewport := get_viewport()
	var visible_size := viewport.get_visible_rect().size
	var zoom := camera.zoom
	var size := Vector2(visible_size.x * zoom.x, visible_size.y * zoom.y)
	var center := camera.get_screen_center_position()
	return Rect2(center - size * 0.5, size)

